import { MATERIALS,SOURCES } from './materials.js';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLessonDocument(teacher=false){return `<!doctype html><html lang="de"><meta charset="utf-8"><title>Ranger Kompakt · ${teacher?'Lehrkräfte':'Arbeitsblätter'}</title><style>body{font:15px/1.6 system-ui;max-width:850px;margin:40px auto;padding:20px;color:#263c32}article{break-inside:avoid;border-top:1px solid #aaa;margin:30px 0}h1,h2{font-family:Georgia;font-weight:400}a{color:#295842}@media print{article{break-before:page}a{overflow-wrap:anywhere}}</style><h1>Ranger Kompakt · ${teacher?'Lehrkräftefassung mit Erwartungskriterien':'Arbeitsblätter und Quellen'}</h1><p>Gestaltetes Modell, keine Naturmessung. Freie Erklärungen besprechen; keine automatische Stichwortbenotung. Pro Kernfamilie 20–35 Minuten als ungeprüftes Planungsziel. gA: Kernfälle; eA: quantitative Flächenprobe und Vertiefungen. Kein Gesamtsammelzwang.</p><p>Curriculare Zuordnung beruht auf den übergebenen Zusammenfassungen: ETS 2025/26 S.27–28, FA SH 2026 S.50–55/62, Leitfaden 2017 gedruckt S.47–49. Original-PDFs lagen dieser Implementierung nicht vor.</p>${MATERIALS.map(c=>`<article><p>${c.id} · ${e(c.level)} · ${e(c.activity)}</p><h2>${e(c.title)}</h2><h3>Material / Herkunft</h3><p>${e(c.data)}</p><h3>Auftrag</h3><p>${e(c.task)}</p><p>Meine Behauptung: __________________________________</p><p>Beleg und Herkunft: _________________________________</p><p>Alternative / Unsicherheit: __________________________</p><p>Transferfrage: Was müsste eine reale Untersuchung anders machen?</p>${teacher?'<h3>Erwartung und zulässige Alternativen</h3><ul>'+c.expected.map(x=>'<li>'+e(x)+'</li>').join('')+'</ul><p>Die Kriterien sind Gesprächs-/Bewertungshilfen, keine Musterformulierung zum Schlüsselwortabgleich. Andere fachlich begründete Belege sind zuzulassen.</p>':''}<p><strong>Grenze:</strong> ${e(c.limit)}</p>${c.sources.map(k=>`<p>${e(SOURCES[k].title)}: <a href="${e(SOURCES[k].url)}">${e(SOURCES[k].url)}</a></p>`).join('')}</article>`).join('')}<h2>Unterrichtspilot: noch durchzuführen</h2><p>Vorher: echte Mindestgeräte festlegen, Steuerung mit Partnern erproben. Im Pilot anonym erfassen: Bearbeitungszeit, Hilfebedarf, Aufgabenverständnis, neue Transferantwort und technische Ausfälle. Keine Schülernamen, Anmeldung oder Cloudübermittlung. Reale Exkursion und Gerätekompetenz getrennt prüfen.</p></html>`;}
